/* -------------------------------------------------------
   Function prototypes
   ------------------------------------------------------- */

int32_t tx_submit_check(bool running, bool has_lane, int64_t bytes, bool has_content);
bool tx_say_enabled(int32_t check);
int32_t tx_field_note(int32_t check, int64_t bytes, bool paused);
int32_t tx_command_return(bool field_focused, bool running);
int32_t tx_line_marker(bool typed);
bool tx_piece_said(bool has_content, int64_t bytes);
int64_t tx_text_len(int64_t len);
bool tx_is_space(uint8_t b);
bool tx_is_continuation(uint8_t b);
int64_t tx_phrase_start(uint8_t text[static 8192], int64_t len, int64_t at);
bool tx_one_letter_before(uint8_t text[static 8192], int64_t i);
int64_t tx_sentence_end_at(uint8_t text[static 8192], int64_t n, int64_t i);
int64_t tx_paragraph_end_at(uint8_t text[static 8192], int64_t n, int64_t i);
int64_t tx_clause_end_at(uint8_t text[static 8192], int64_t n, int64_t i);
int64_t tx_phrase_end(uint8_t text[static 8192], int64_t len, int64_t start);
int64_t tx_fixture(int64_t index, uint8_t out[static 8192], int64_t at);
int64_t tx_fixture_len(int64_t index);

/* -------------------------------------------------------
   Function implementations
   ------------------------------------------------------- */

int32_t tx_submit_check(bool running, bool has_lane, int64_t bytes, bool has_content) {
    if ((running == false)) {
        return TX_SUBMIT_NOT_RUNNING;
    }
    if ((has_lane == false)) {
        return TX_SUBMIT_NO_LANE;
    }
    if ((has_content == false)) {
        return TX_SUBMIT_EMPTY;
    }
    if ((bytes > TX_MAX_BYTES)) {
        return TX_SUBMIT_TOO_LONG;
    }
    return TX_SUBMIT_OK;
}

bool tx_say_enabled(int32_t check) {
    return (check == TX_SUBMIT_OK);
}

int32_t tx_field_note(int32_t check, int64_t bytes, bool paused) {
    if ((check == TX_SUBMIT_TOO_LONG)) {
        return TX_NOTE_TOO_LONG;
    }
    if ((check == TX_SUBMIT_NOT_RUNNING)) {
        if ((bytes > 0)) {
            return TX_NOTE_NEEDS_START;
        }
        return TX_NOTE_NONE;
    }
    if ((check == TX_SUBMIT_NO_LANE)) {
        return TX_NOTE_NO_LANE;
    }
    if (paused) {
        return TX_NOTE_PAUSED;
    }
    return TX_NOTE_NONE;
}

int32_t tx_command_return(bool field_focused, bool running) {
    if ((field_focused && running)) {
        return TX_CMDRET_SAY;
    }
    return TX_CMDRET_RUN;
}

int32_t tx_line_marker(bool typed) {
    if (typed) {
        return TX_MARK_KEYBOARD;
    }
    return TX_MARK_NONE;
}

bool tx_piece_said(bool has_content, int64_t bytes) {
    return (has_content && (bytes > 0));
}

int64_t tx_text_len(int64_t len) {
    if ((len < 0)) {
        return 0;
    }
    if ((len > TX_TEXT_MAX)) {
        return TX_TEXT_MAX;
    }
    return len;
}

bool tx_is_space(uint8_t b) {
    return ((((b == TX_SPACE) || (b == TX_TAB)) || (b == TX_LF)) || (b == TX_CR));
}

bool tx_is_continuation(uint8_t b) {
    return ((b & TX_CONTINUATION_MASK) == TX_CONTINUATION);
}

int64_t tx_phrase_start(uint8_t text[static 8192], int64_t len, int64_t at) {
    int64_t n = tx_text_len(len);
    int64_t i = at;
    if ((i < 0)) {
        i = 0;
    }
    if ((i >= n)) {
        return n;
    }
    while (((i < n) && tx_is_space(text[i]))) {
        i = (i + 1);
    }
    return i;
}

bool tx_one_letter_before(uint8_t text[static 8192], int64_t i) {
    if ((i >= 1)) {
        uint8_t b = text[(i - 1)];
        if (((((b >= 48) && (b <= 57)) || ((b >= 65) && (b <= 90))) || ((b >= 97) && (b <= 122)))) {
            return ((i == 1) || tx_is_space(text[(i - 2)]));
        }
    }
    if ((i >= 2)) {
        uint8_t lead = text[(i - 2)];
        if ((((lead >= TX_LEAD_LETTER_FIRST) && (lead <= TX_LEAD_LETTER_LAST)) && tx_is_continuation(text[(i - 1)]))) {
            return ((i == 2) || tx_is_space(text[(i - 3)]));
        }
    }
    return false;
}

int64_t tx_sentence_end_at(uint8_t text[static 8192], int64_t n, int64_t i) {
    uint8_t b = text[i];
    int64_t e = -1;
    if (((b == TX_EXCLAMATION) || (b == TX_QUESTION))) {
        e = (i + 1);
    } else if ((b == TX_DOT)) {
        if ((tx_one_letter_before(text, i) == false)) {
            e = (i + 1);
        }
    } else if (((((b == TX_LEAD_E2) && ((i + 2) < n)) && (text[(i + 1)] == TX_SECOND_80)) && (text[(i + 2)] == TX_ELLIPSIS))) {
        e = (i + 3);
    }
    if ((e < 0)) {
        return -1;
    }
    bool closing = true;
    while ((closing && (e < n))) {
        uint8_t c = text[e];
        if ((((c == TX_QUOTE) || (c == TX_APOSTROPHE)) || (c == TX_PAREN_CLOSE))) {
            e = (e + 1);
        } else if ((((c == TX_LEAD_C2) && ((e + 1) < n)) && (text[(e + 1)] == TX_GUILLEMET_CLOSE))) {
            e = (e + 2);
        } else if (((((c == TX_LEAD_E2) && ((e + 2) < n)) && (text[(e + 1)] == TX_SECOND_80)) && (text[(e + 2)] == TX_CURLY_CLOSE))) {
            e = (e + 3);
        } else {
            closing = false;
        }
    }
    if ((e == n)) {
        return e;
    }
    if (tx_is_space(text[e])) {
        return e;
    }
    return -1;
}

int64_t tx_paragraph_end_at(uint8_t text[static 8192], int64_t n, int64_t i) {
    if ((text[i] != TX_LF)) {
        return -1;
    }
    int64_t j = (i + 1);
    while (((j < n) && (((text[j] == TX_SPACE) || (text[j] == TX_TAB)) || (text[j] == TX_CR)))) {
        j = (j + 1);
    }
    if (((j < n) && (text[j] == TX_LF))) {
        return i;
    }
    return -1;
}

int64_t tx_clause_end_at(uint8_t text[static 8192], int64_t n, int64_t i) {
    uint8_t b = text[i];
    int64_t e = -1;
    if ((((b == TX_COMMA) || (b == TX_SEMICOLON)) || (b == TX_COLON))) {
        e = (i + 1);
    } else if (((((b == TX_LEAD_E2) && ((i + 2) < n)) && (text[(i + 1)] == TX_SECOND_80)) && ((text[(i + 2)] == TX_EM_DASH) || (text[(i + 2)] == TX_EN_DASH)))) {
        e = (i + 3);
    }
    if (((e < 0) || (e >= n))) {
        return -1;
    }
    if (tx_is_space(text[e])) {
        return e;
    }
    return -1;
}

int64_t tx_phrase_end(uint8_t text[static 8192], int64_t len, int64_t start) {
    int64_t n = tx_text_len(len);
    int64_t s = start;
    if ((s < 0)) {
        s = 0;
    }
    if ((s >= n)) {
        return n;
    }
    int64_t limit = n;
    if (((n - s) > TX_PHRASE_MAX_BYTES)) {
        limit = (s + TX_PHRASE_MAX_BYTES);
    }
    int64_t line_cut = -1;
    int64_t clause_cut = -1;
    int64_t space_cut = -1;
    int64_t i = s;
    while ((i < limit)) {
        int64_t e = tx_sentence_end_at(text, n, i);
        if ((e < 0)) {
            e = tx_paragraph_end_at(text, n, i);
        }
        if ((((e >= 0) && (e <= limit)) && ((e - s) >= TX_PHRASE_MIN_BYTES))) {
            int64_t tail = tx_phrase_start(text, n, e);
            if (((tail >= n) || ((n - tail) >= TX_PHRASE_MIN_BYTES))) {
                return e;
            }
        }
        if (((i - s) >= TX_PHRASE_MIN_BYTES)) {
            if ((text[i] == TX_LF)) {
                line_cut = i;
            }
            if (tx_is_space(text[i])) {
                space_cut = i;
            }
        }
        int64_t c = tx_clause_end_at(text, n, i);
        if ((((c >= 0) && (c <= limit)) && ((c - s) >= TX_PHRASE_MIN_BYTES))) {
            clause_cut = c;
        }
        i = (i + 1);
    }
    if ((limit == n)) {
        return n;
    }
    if ((line_cut >= 0)) {
        return line_cut;
    }
    if ((clause_cut >= 0)) {
        return clause_cut;
    }
    if ((space_cut >= 0)) {
        return space_cut;
    }
    int64_t j = limit;
    while (((j > s) && tx_is_continuation(text[j]))) {
        j = (j - 1);
    }
    if ((j > s)) {
        return j;
    }
    return limit;
}

int64_t tx_fixture(int64_t index, uint8_t out[static 8192], int64_t at) {
    if ((((index < 0) || (index >= TX_FX_COUNT)) || (at < 0))) {
        return 0;
    }
    int64_t off = TX_FX_OFFSETS[index];
    int64_t len = TX_FX_LENGTHS[index];
    int64_t k = 0;
    while (((k < len) && ((at + k) < TX_TEXT_MAX))) {
        out[(at + k)] = TX_FX_TEXT[(off + k)];
        k = (k + 1);
    }
    return k;
}

int64_t tx_fixture_len(int64_t index) {
    if (((index < 0) || (index >= TX_FX_COUNT))) {
        return 0;
    }
    int64_t len = TX_FX_LENGTHS[index];
    return len;
}

/* -------------------------------------------------------
   Tests
   ------------------------------------------------------- */

void test_tx_submit_rules(void) {
    assert((tx_submit_check(false, false, 0, false) == TX_SUBMIT_NOT_RUNNING));
    assert((tx_submit_check(false, true, 10, true) == TX_SUBMIT_NOT_RUNNING));
    assert((tx_submit_check(true, false, 10, true) == TX_SUBMIT_NO_LANE));
    assert((tx_submit_check(true, true, 0, false) == TX_SUBMIT_EMPTY));
    assert((tx_submit_check(true, true, 9000, false) == TX_SUBMIT_EMPTY));
    assert((tx_submit_check(true, true, 4000, true) == TX_SUBMIT_OK));
    assert((tx_submit_check(true, true, 4001, true) == TX_SUBMIT_TOO_LONG));
    assert((tx_submit_check(true, true, 2, true) == TX_SUBMIT_OK));
    assert((tx_say_enabled(TX_SUBMIT_OK) == true));
    uint32_t bad = 0;
    int32_t bits = 0;
    while ((bits < 8)) {
        bool running = ((bits & 1) != 0);
        bool lane = ((bits & 2) != 0);
        bool content = ((bits & 4) != 0);
        int64_t b = -2;
        while ((b <= (TX_MAX_BYTES + 2))) {
            int32_t check = tx_submit_check(running, lane, b, content);
            bool fits = (b <= TX_MAX_BYTES);
            if ((tx_say_enabled(check) != (((running && lane) && content) && fits))) {
                bad = (bad + 1);
            }
            if (((check < TX_SUBMIT_OK) || (check > TX_SUBMIT_TOO_LONG))) {
                bad = (bad + 1);
            }
            b = (b + 1);
        }
        bits = (bits + 1);
    }
    assert((bad == 0));
    assert((tx_say_enabled(TX_SUBMIT_NOT_RUNNING) == false));
    assert((tx_say_enabled(TX_SUBMIT_NO_LANE) == false));
    assert((tx_say_enabled(TX_SUBMIT_EMPTY) == false));
    assert((tx_say_enabled(TX_SUBMIT_TOO_LONG) == false));
    assert((tx_field_note(TX_SUBMIT_TOO_LONG, 5000, true) == TX_NOTE_TOO_LONG));
    assert((tx_field_note(TX_SUBMIT_NOT_RUNNING, 3, false) == TX_NOTE_NEEDS_START));
    assert((tx_field_note(TX_SUBMIT_NOT_RUNNING, 0, true) == TX_NOTE_NONE));
    assert((tx_field_note(TX_SUBMIT_NO_LANE, 0, true) == TX_NOTE_NO_LANE));
    assert((tx_field_note(TX_SUBMIT_OK, 10, true) == TX_NOTE_PAUSED));
    assert((tx_field_note(TX_SUBMIT_EMPTY, 0, true) == TX_NOTE_PAUSED));
    assert((tx_field_note(TX_SUBMIT_OK, 10, false) == TX_NOTE_NONE));
    assert((tx_field_note(TX_SUBMIT_EMPTY, 0, false) == TX_NOTE_NONE));
    assert((tx_command_return(true, true) == TX_CMDRET_SAY));
    assert((tx_command_return(true, false) == TX_CMDRET_RUN));
    assert((tx_command_return(false, true) == TX_CMDRET_RUN));
    assert((tx_command_return(false, false) == TX_CMDRET_RUN));
    assert((tx_line_marker(true) == TX_MARK_KEYBOARD));
    assert((tx_line_marker(false) == TX_MARK_NONE));
    assert((tx_piece_said(true, 5) == true));
    assert((tx_piece_said(false, 5) == false));
    assert((tx_piece_said(true, 0) == false));
}

void test_tx_phrase_rules(void) {
    uint8_t t[8192] = { [0 ... (8192) - 1] = 0 };
    int64_t n = tx_fixture(TX_FX_THREE, t, 0);
    int64_t e = tx_phrase_end(t, n, 0);
    assert((e == tx_fixture_len(TX_FX_THREE_1)));
    int64_t s = tx_phrase_start(t, n, e);
    assert((s == (e + 1)));
    e = tx_phrase_end(t, n, s);
    assert(((e - s) == tx_fixture_len(TX_FX_THREE_2)));
    s = tx_phrase_start(t, n, e);
    assert((tx_phrase_end(t, n, s) == n));
    assert(((n - s) == tx_fixture_len(TX_FX_THREE_3)));
    n = tx_fixture(TX_FX_SHORT, t, 0);
    assert((tx_phrase_end(t, n, 0) == n));
    n = tx_fixture(TX_FX_LATIN, t, 0);
    assert((tx_phrase_end(t, n, 0) == n));
    n = tx_fixture(TX_FX_ABBREV, t, 0);
    assert((tx_phrase_end(t, n, 0) == n));
    n = tx_fixture(TX_FX_INITIAL, t, 0);
    assert((tx_phrase_end(t, n, 0) == tx_fixture_len(TX_FX_INITIAL_1)));
    n = tx_fixture(TX_FX_QUOTE, t, 0);
    assert((tx_phrase_end(t, n, 0) == tx_fixture_len(TX_FX_QUOTE_1)));
    n = tx_fixture(TX_FX_BANG, t, 0);
    assert((tx_phrase_end(t, n, 0) == tx_fixture_len(TX_FX_BANG_1)));
    n = tx_fixture(TX_FX_ELLIPSIS, t, 0);
    assert((tx_phrase_end(t, n, 0) == tx_fixture_len(TX_FX_ELLIPSIS_1)));
    n = tx_fixture(TX_FX_DECIMAL, t, 0);
    assert((tx_phrase_end(t, n, 0) == tx_fixture_len(TX_FX_DECIMAL_1)));
    n = tx_fixture(TX_FX_PARAGRAPH, t, 0);
    assert((tx_phrase_end(t, n, 0) == tx_fixture_len(TX_FX_PARAGRAPH_1)));
    n = tx_fixture(TX_FX_LINES, t, 0);
    assert((tx_phrase_end(t, n, 0) == n));
    n = tx_fixture(TX_FX_SMILES, t, 0);
    assert((tx_phrase_end(t, n, 0) == tx_fixture_len(TX_FX_SMILES_1)));
    n = tx_fixture(TX_FX_LIST_LONG, t, 0);
    assert((n > TX_PHRASE_MAX_BYTES));
    assert((tx_phrase_end(t, n, 0) == tx_fixture_len(TX_FX_LIST_LONG_1)));
    n = tx_fixture(TX_FX_COMMAS_LONG, t, 0);
    assert((n > TX_PHRASE_MAX_BYTES));
    e = tx_phrase_end(t, n, 0);
    assert((e <= TX_PHRASE_MAX_BYTES));
    assert((e > (TX_PHRASE_MAX_BYTES - 40)));
    assert((t[(e - 1)] == TX_COMMA));
    assert((t[e] == TX_SPACE));
    s = tx_phrase_start(t, n, e);
    assert((tx_phrase_end(t, n, s) == n));
    n = tx_fixture(TX_FX_WORDS_LONG, t, 0);
    e = tx_phrase_end(t, n, 0);
    assert((e <= TX_PHRASE_MAX_BYTES));
    assert((e > (TX_PHRASE_MAX_BYTES - 12)));
    assert((t[e] == TX_SPACE));
    n = tx_fixture(TX_FX_ZHE_LONG, t, 0);
    assert((tx_phrase_end(t, n, 0) == TX_PHRASE_MAX_BYTES));
    assert((tx_phrase_end(t, n, 1) == TX_PHRASE_MAX_BYTES));
    assert((tx_phrase_end(t, n, TX_PHRASE_MAX_BYTES) == n));
    n = tx_fixture(TX_FX_SPACES, t, 0);
    assert((tx_phrase_start(t, n, 0) == n));
    assert((tx_phrase_start(t, 0, 0) == 0));
    assert((tx_phrase_end(t, 0, 0) == 0));
    n = tx_fixture(TX_FX_THREE, t, 0);
    assert((tx_phrase_start(t, n, -5) == 0));
    assert((tx_phrase_start(t, n, (n + 5)) == n));
    assert((tx_phrase_end(t, n, (n + 5)) == n));
    assert((tx_phrase_end(t, n, -5) == tx_fixture_len(TX_FX_THREE_1)));
    int64_t fx = 0;
    uint32_t bad = 0;
    while ((fx < TX_FX_COUNT)) {
        n = tx_fixture(fx, t, 0);
        int64_t st = 0;
        while ((st < n)) {
            int64_t en = tx_phrase_end(t, n, st);
            if ((((en <= st) || (en > n)) || ((en - st) > TX_PHRASE_MAX_BYTES))) {
                bad = (bad + 1);
            }
            if ((((en < n) && tx_is_continuation(t[en])) && (tx_is_continuation(t[st]) == false))) {
                bad = (bad + 1);
            }
            st = (st + 1);
        }
        fx = (fx + 1);
    }
    assert((bad == 0));
    assert((tx_text_len(-1) == 0));
    assert((tx_text_len((TX_TEXT_MAX + 1)) == TX_TEXT_MAX));
}

void test_tx_boundary_rules(void) {
    uint8_t t[8192] = { [0 ... (8192) - 1] = 0 };
    t[0] = 97;
    t[1] = TX_DOT;
    t[2] = TX_SPACE;
    t[3] = 98;
    assert((tx_one_letter_before(t, 1) == true));
    assert((tx_sentence_end_at(t, 4, 1) == -1));
    t[0] = 97;
    t[1] = 98;
    t[2] = TX_DOT;
    t[3] = TX_SPACE;
    assert((tx_one_letter_before(t, 2) == false));
    assert((tx_sentence_end_at(t, 4, 2) == 3));
    assert((tx_sentence_end_at(t, 3, 2) == 3));
    t[0] = 49;
    t[1] = 53;
    t[2] = TX_DOT;
    t[3] = 52;
    assert((tx_one_letter_before(t, 2) == false));
    assert((tx_sentence_end_at(t, 4, 2) == -1));
    t[0] = 120;
    t[1] = TX_EXCLAMATION;
    t[2] = TX_PAREN_CLOSE;
    t[3] = TX_SPACE;
    assert((tx_sentence_end_at(t, 4, 1) == 3));
    t[0] = TX_LF;
    t[1] = TX_SPACE;
    t[2] = TX_CR;
    t[3] = TX_LF;
    assert((tx_paragraph_end_at(t, 4, 0) == 0));
    assert((tx_paragraph_end_at(t, 3, 0) == -1));
    assert((tx_paragraph_end_at(t, 4, 1) == -1));
    t[0] = 97;
    t[1] = TX_COMMA;
    t[2] = TX_SPACE;
    assert((tx_clause_end_at(t, 3, 1) == 2));
    assert((tx_clause_end_at(t, 2, 1) == -1));
    t[2] = 98;
    assert((tx_clause_end_at(t, 3, 1) == -1));
    uint32_t b = 0;
    uint32_t spaces = 0;
    uint32_t continuations = 0;
    while ((b < 256)) {
        if (tx_is_space(((uint8_t)(b)))) {
            spaces = (spaces + 1);
        }
        if (tx_is_continuation(((uint8_t)(b)))) {
            continuations = (continuations + 1);
        }
        b = (b + 1);
    }
    assert((spaces == 4));
    assert((continuations == 64));
}


